S1="S1 Arterial Doppler Waveform Analysis"; S2="S2 SVM/SVU Consensus 2020"; S3="S3 Radiology Key Venous Insufficiency"; S4="S4 Venous Ultrasound 2e Ch.10"
OUT="OUTSIDE SOURCE"
def sel(id,label,options,src=None,**k): d={"id":id,"label":label,"type":"select","options":options}; d.update(k); src and d.update(source=src); return d
def msel(id,label,options,src=None,**k): d=sel(id,label,options,src,**k); d["type"]="multiselect"; return d
def num(id,label,unit,src=None,**k): d={"id":id,"label":label,"type":"number","unit":unit}; d.update(k); src and d.update(source=src); return d
def chk(id,label,src=None,**k): d={"id":id,"label":label,"type":"checkbox"}; d.update(k); src and d.update(source=src); return d
def txt(id,label,**k): d={"id":id,"label":label,"type":"text"}; d.update(k); return d

