  sel("group","Group",["thigh - medial","thigh - anterior","thigh - lateral","thigh - posterior","knee","calf - medial (paratibial)","calf - medial (posterior tibial)","calf - anterior","calf - lateral","calf - posterior (gastrocnemius/soleal/para-Achillean)"],S3+" p.10"),
  num("distance","Distance from heel/medial malleolus or knee crease","cm",OUT),
