 ["DFV","deep femoral vein, proximal",False,"proximal"],["FV_P","proximal femoral vein",False,"proximal"],["FV_M","mid femoral vein",False,"proximal"],["FV_D","distal femoral vein",False,"proximal"],
 ["POPV","popliteal vein",False,"proximal"],["PTV","posterior tibial veins",False,"distal"],["PERV","peroneal veins",False,"distal"],["GCV","gastrocnemius veins",True,"distal"],["SOV","soleal veins",True,"distal"],
